				context.collision = true;
				context.overshoot = Math.abs(buffer - vec.z);
				vec = new Vec3d(vec.x, vec.y, buffer);
				return vec;
			}

			info.dist(Math.abs(targetZ - vec.z) * Math.signum(speed));
			info.pos(new BlockPos(cX, y, cZ + (motionZ * speed > 0 ? 3 : -3)));
		}

